with account_totals as (select account_id, sort_array(collect_set(txn_type)) as txn_type_list, round((100 * sum(case when txn_type = 'REFUND' then 1 else 0 end)) / count(*), 1) as pct_refund from transactions where txn_type in ('REFUND', 'CREDIT', 'DEBIT') group by account_id) select a.id, a.customer_id, at.txn_type_list, at.pct_refund from accounts a left join account_totals at on a.id = at.account_id where at.pct_refund > 67 order by customer_id desc;
